mapper.select:
SELECT r.*, m.name AS owner_name
FROM pm_risk r LEFT JOIN pm_member m ON r.owner_id = m.id
WHERE r.id = #{id}

mapper.update:
UPDATE pm_risk
SET title = #{title}, category = #{category}, probability = #{probability},
    impact = #{impact}, level = #{level}, status = #{status},
    mitigation = #{mitigation}, owner_id = #{ownerId},
    identified_date = #{identifiedDate}, resolved_date = #{resolvedDate}
WHERE id = #{id}
